function results = opf_case14(bus_PD_10, branch_RATE_A_9_10)
    define_constants;
    mpc = loadcase('case14');

    bus10_idx = find(mpc.bus(:, BUS_I) == 10);
    pd0_bus10 = mpc.bus(bus10_idx, PD);
    assert(bus_PD_10 >= pd0_bus10);
    mpc.bus(bus10_idx, PD) = bus_PD_10;

    branch_idx = find( ...
        (mpc.branch(:, F_BUS) == 9 & mpc.branch(:, T_BUS) == 10) | ...
        (mpc.branch(:, F_BUS) == 10 & mpc.branch(:, T_BUS) == 9) );
    rate0_9_10 = mpc.branch(branch_idx, RATE_A);
    assert(all(branch_RATE_A_9_10 <= rate0_9_10));
    mpc.branch(branch_idx, RATE_A) = branch_RATE_A_9_10;

    mpopt = mpoption('opf.violation', 1e-6, 'opf.ac.solver', 'MIPS');
    results = runopf(mpc, mpopt);
    printpf(results);
end

